// Data model (LLD §2). Enumerations are text + CHECK, timestamps are timestamptz, ids are UUIDv7
// generated by the application. Migrations are generated from this file with drizzle-kit and are
// never edited after merge (NFR-REL-03).
import { sql } from 'drizzle-orm';
import {
  bigint,
  bigserial,
  boolean,
  check,
  customType,
  index,
  inet,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType() {
    return 'bytea';
  },
});

const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const createdAt = () => tstz('created_at').notNull().defaultNow();

export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    username: text('username').notNull(),
    displayName: text('display_name').notNull().default(''),
    avatarKey: text('avatar_key'),
    /** WebAuthn user handle: 32 random bytes, never the database id (ADR-0018). */
    webauthnUserId: bytea('webauthn_user_id'),
    role: text('role', { enum: ['member', 'admin'] })
      .notNull()
      .default('member'),
    status: text('status', { enum: ['active', 'suspended'] })
      .notNull()
      .default('active'),
    storageBytes: bigint('storage_bytes', { mode: 'number' }).notNull().default(0),
    quotaBytesOverride: bigint('quota_bytes_override', { mode: 'number' }),
    lastActiveAt: tstz('last_active_at'),
    createdAt: createdAt(),
    updatedAt: tstz('updated_at').notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('users_username_key').on(t.username),
    uniqueIndex('users_webauthn_user_id_key').on(t.webauthnUserId),
    index('users_display_name_trgm').using('gin', sql`${t.displayName} gin_trgm_ops`),
    check('users_username_format', sql`${t.username} ~ '^[a-z0-9][a-z0-9_.]{2,29}$'`),
    check('users_role_check', sql`${t.role} in ('member','admin')`),
    check('users_status_check', sql`${t.status} in ('active','suspended')`),
    check('users_display_name_length', sql`char_length(${t.displayName}) <= 50`),
  ],
);

export const sessions = pgTable(
  'sessions',
  {
    tokenHash: bytea('token_hash').primaryKey(),
    id: uuid('id').notNull(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    client: text('client', { enum: ['web', 'mobile'] }).notNull(),
    userAgent: text('user_agent').notNull().default(''),
    createdAt: createdAt(),
    lastSeenAt: tstz('last_seen_at').notNull().defaultNow(),
    idleExpiresAt: tstz('idle_expires_at').notNull(),
    absoluteExpiresAt: tstz('absolute_expires_at').notNull(),
    /** The passkey that created the session; removing it revokes the session (FR-ACCT-02). */
    passkeyId: uuid('passkey_id').references(() => passkeys.id, { onDelete: 'cascade' }),
    /** Last passkey confirmation, for sensitive actions within 5 minutes (WF-ACCT-2/3). */
    reauthAt: tstz('reauth_at'),
  },
  (t) => [
    index('sessions_user_id_idx').on(t.userId),
    uniqueIndex('sessions_id_key').on(t.id),
    check('sessions_client_check', sql`${t.client} in ('web','mobile')`),
  ],
);

export const invites = pgTable(
  'invites',
  {
    id: uuid('id').primaryKey(),
    codeHash: bytea('code_hash').notNull(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    maxUses: integer('max_uses').notNull().default(1),
    uses: integer('uses').notNull().default(0),
    autoFriend: boolean('auto_friend').notNull().default(true),
    expiresAt: tstz('expires_at').notNull(),
    revokedAt: tstz('revoked_at'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('invites_code_hash_key').on(t.codeHash),
    index('invites_created_by_idx').on(t.createdBy, t.createdAt),
    check('invites_max_uses_range', sql`${t.maxUses} between 1 and 50`),
    check('invites_uses_le_max', sql`${t.uses} >= 0 and ${t.uses} <= ${t.maxUses}`),
  ],
);

export const inviteRedemptions = pgTable(
  'invite_redemptions',
  {
    inviteId: uuid('invite_id')
      .notNull()
      .references(() => invites.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.inviteId, t.userId] })],
);

/** One row per unordered pair (BR-FRND-2). */
export const relationships = pgTable(
  'relationships',
  {
    userLow: uuid('user_low')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    userHigh: uuid('user_high')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    // 'none' is a tombstone that only carries a decline cooldown (BR-FRND-4).
    state: text('state', { enum: ['none', 'pending', 'accepted', 'blocked'] }).notNull(),
    requestedBy: uuid('requested_by'),
    blockedBy: uuid('blocked_by'),
    cooldownUntil: tstz('cooldown_until'),
    createdAt: createdAt(),
    updatedAt: tstz('updated_at').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.userLow, t.userHigh] }),
    check('relationships_order', sql`${t.userLow} < ${t.userHigh}`),
    check('relationships_state_check', sql`${t.state} in ('none','pending','accepted','blocked')`),
    check(
      'relationships_state_fields',
      sql`(${t.state} <> 'pending' or ${t.requestedBy} is not null) and (${t.state} <> 'blocked' or ${t.blockedBy} is not null)`,
    ),
    index('relationships_low_accepted')
      .on(t.userLow)
      .where(sql`${t.state} = 'accepted'`),
    index('relationships_high_accepted')
      .on(t.userHigh)
      .where(sql`${t.state} = 'accepted'`),
  ],
);

export const instanceSettings = pgTable('instance_settings', {
  key: text('key').primaryKey(),
  value: jsonb('value').notNull(),
  updatedBy: uuid('updated_by'),
  updatedAt: tstz('updated_at').notNull().defaultNow(),
});

/** Recovery links (WF-ADM-4, ADR-0018); `created_by` is null when the server command made it. */
export const recoveryTokens = pgTable(
  'recovery_tokens',
  {
    tokenHash: bytea('token_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdBy: uuid('created_by').references(() => users.id, { onDelete: 'set null' }),
    expiresAt: tstz('expires_at').notNull(),
    usedAt: tstz('used_at'),
    createdAt: createdAt(),
  },
  (t) => [index('recovery_tokens_user_idx').on(t.userId)],
);

/** Passkeys (WebAuthn discoverable credentials), the only credential (ADR-0018). */
export const passkeys = pgTable(
  'passkeys',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    credentialId: text('credential_id').notNull(),
    publicKey: bytea('public_key').notNull(),
    counter: bigint('counter', { mode: 'number' }).notNull().default(0),
    transports: text('transports')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    backedUp: boolean('backed_up').notNull().default(false),
    name: text('name').notNull(),
    createdAt: createdAt(),
    lastUsedAt: tstz('last_used_at'),
  },
  (t) => [
    uniqueIndex('passkeys_credential_id_key').on(t.credentialId),
    index('passkeys_user_idx').on(t.userId),
  ],
);

/** Single-use WebAuthn challenges, 5 minutes (ADR-0018). */
export const webauthnChallenges = pgTable(
  'webauthn_challenges',
  {
    id: uuid('id').primaryKey(),
    challenge: text('challenge').notNull(),
    purpose: text('purpose', {
      enum: ['setup', 'register', 'recover', 'add', 'signin', 'reauth'],
    }).notNull(),
    userId: uuid('user_id').references(() => users.id, { onDelete: 'cascade' }),
    context: jsonb('context').notNull().default({}),
    expiresAt: tstz('expires_at').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index('webauthn_challenges_expires_idx').on(t.expiresAt),
    check(
      'webauthn_challenges_purpose_check',
      sql`${t.purpose} in ('setup','register','recover','add','signin','reauth')`,
    ),
  ],
);

/** Browser hand-off codes for the mobile app (WF-AUTH-5): 60 seconds, single use, PKCE-bound. */
export const mobileAuthCodes = pgTable(
  'mobile_auth_codes',
  {
    codeHash: bytea('code_hash').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    passkeyId: uuid('passkey_id').references(() => passkeys.id, { onDelete: 'cascade' }),
    codeChallenge: text('code_challenge').notNull(),
    expiresAt: tstz('expires_at').notNull(),
    usedAt: tstz('used_at'),
    createdAt: createdAt(),
  },
  (t) => [index('mobile_auth_codes_expires_idx').on(t.expiresAt)],
);

/** Append-only (enforced by a trigger, see migration 0000); no FK so entries survive deletion. */
export const auditLog = pgTable(
  'audit_log',
  {
    id: bigserial('id', { mode: 'number' }).primaryKey(),
    actorId: uuid('actor_id'),
    action: text('action').notNull(),
    targetType: text('target_type'),
    targetId: text('target_id'),
    metadata: jsonb('metadata').notNull().default({}),
    ip: inet('ip'),
    createdAt: createdAt(),
  },
  (t) => [
    index('audit_log_created_at_idx').on(t.createdAt.desc()),
    index('audit_log_actor_idx').on(t.actorId),
    index('audit_log_action_idx').on(t.action),
  ],
);

export const VIDEO_STATES = [
  'queued',
  'fetching',
  'processing',
  'ready',
  'link_only',
  'failed',
  'expired',
] as const;

export const videos = pgTable(
  'videos',
  {
    id: uuid('id').primaryKey(),
    addedBy: uuid('added_by').references(() => users.id, { onDelete: 'set null' }),
    sourceKind: text('source_kind', { enum: ['link', 'upload'] }).notNull(),
    sourceUrl: text('source_url'),
    normalizedUrl: text('normalized_url'),
    platform: text('platform'),
    sha256: bytea('sha256'),
    state: text('state', { enum: VIDEO_STATES }).notNull(),
    failureReason: text('failure_reason'),
    title: text('title').notNull().default(''),
    authorHandle: text('author_handle'),
    durationMs: integer('duration_ms'),
    width: integer('width'),
    height: integer('height'),
    mediaKey: text('media_key'),
    thumbKey: text('thumb_key'),
    mediaBytes: bigint('media_bytes', { mode: 'number' }).notNull().default(0),
    createdAt: createdAt(),
    updatedAt: tstz('updated_at').notNull().defaultNow(),
    readyAt: tstz('ready_at'),
    expiredAt: tstz('expired_at'),
  },
  (t) => [
    uniqueIndex('videos_normalized_url_key')
      .on(t.normalizedUrl)
      .where(sql`${t.normalizedUrl} is not null`),
    uniqueIndex('videos_sha256_key')
      .on(t.sha256)
      .where(sql`${t.sha256} is not null`),
    index('videos_added_by_idx').on(t.addedBy),
    index('videos_state_idx').on(t.state),
    check('videos_source_kind_check', sql`${t.sourceKind} in ('link','upload')`),
    check(
      'videos_state_check',
      sql`${t.state} in ('queued','fetching','processing','ready','link_only','failed','expired')`,
    ),
    check('videos_title_length', sql`char_length(${t.title}) <= 200`),
  ],
);

/** Every member who added a video (by link or upload). Dedup reuses media, never ownership (BR-MED-4). */
export const videoAdditions = pgTable(
  'video_additions',
  {
    videoId: uuid('video_id')
      .notNull()
      .references(() => videos.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ columns: [t.videoId, t.userId] }),
    index('video_additions_user_idx').on(t.userId),
  ],
);

export const uploads = pgTable(
  'uploads',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    objectKey: text('object_key').notNull(),
    declaredBytes: bigint('declared_bytes', { mode: 'number' }).notNull(),
    contentType: text('content_type').notNull(),
    multipartId: text('multipart_id'),
    state: text('state', { enum: ['pending', 'completed', 'aborted'] })
      .notNull()
      .default('pending'),
    videoId: uuid('video_id').references(() => videos.id, { onDelete: 'set null' }),
    expiresAt: tstz('expires_at').notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index('uploads_user_idx').on(t.userId),
    check('uploads_state_check', sql`${t.state} in ('pending','completed','aborted')`),
  ],
);

export const REACTION_SET = ['👍', '❤️', '😂', '😮', '😢', '🔥'] as const;

export const shares = pgTable(
  'shares',
  {
    id: uuid('id').primaryKey(),
    videoId: uuid('video_id')
      .notNull()
      .references(() => videos.id, { onDelete: 'cascade' }),
    senderId: uuid('sender_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    recipientId: uuid('recipient_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    note: text('note').notNull().default(''),
    deliveredAt: tstz('delivered_at'),
    watchedAt: tstz('watched_at'),
    progressMs: integer('progress_ms').notNull().default(0),
    saved: boolean('saved').notNull().default(false),
    savedAt: tstz('saved_at'),
    hidden: boolean('hidden').notNull().default(false),
    reaction: text('reaction'),
    reactionAt: tstz('reaction_at'),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex('shares_sender_recipient_video_key').on(t.senderId, t.recipientId, t.videoId),
    index('shares_feed_idx')
      .on(t.recipientId, t.watchedAt.nullsFirst(), t.deliveredAt, t.id)
      .where(sql`${t.hidden} = false and ${t.deliveredAt} is not null`),
    index('shares_sender_idx').on(t.senderId, t.createdAt.desc()),
    index('shares_video_idx').on(t.videoId),
    index('shares_recipient_saved_idx')
      .on(t.recipientId, t.savedAt.desc())
      .where(sql`${t.saved}`),
    check('shares_not_self', sql`${t.senderId} <> ${t.recipientId}`),
    check('shares_note_length', sql`char_length(${t.note}) <= 500`),
    check(
      'shares_reaction_check',
      sql`${t.reaction} is null or ${t.reaction} in ('👍','❤️','😂','😮','😢','🔥')`,
    ),
  ],
);

/** Send idempotency (WF-SHR-1): retries with the same key within 24 h return the stored result. */
export const sendRequests = pgTable(
  'send_requests',
  {
    senderId: uuid('sender_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    idempotencyKey: text('idempotency_key').notNull(),
    response: jsonb('response').notNull(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.senderId, t.idempotencyKey] })],
);

export const replies = pgTable(
  'replies',
  {
    id: uuid('id').primaryKey(),
    shareId: uuid('share_id')
      .notNull()
      .references(() => shares.id, { onDelete: 'cascade' }),
    authorId: uuid('author_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    body: text('body').notNull(),
    deletedAt: tstz('deleted_at'),
    createdAt: createdAt(),
  },
  (t) => [
    index('replies_share_idx').on(t.shareId, t.createdAt),
    check('replies_body_length', sql`char_length(${t.body}) between 1 and 1000`),
  ],
);

export const NOTIFICATION_TYPE_LIST = [
  'share_received',
  'reaction_received',
  'reply_received',
  'friend_request_received',
  'friend_request_accepted',
  'share_watched',
] as const;

export const notifications = pgTable(
  'notifications',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    type: text('type', { enum: NOTIFICATION_TYPE_LIST }).notNull(),
    actorId: uuid('actor_id').references(() => users.id, { onDelete: 'set null' }),
    shareId: uuid('share_id').references(() => shares.id, { onDelete: 'cascade' }),
    data: jsonb('data').notNull().default({}),
    readAt: tstz('read_at'),
    pushedAt: tstz('pushed_at'),
    createdAt: createdAt(),
  },
  (t) => [
    index('notifications_user_idx').on(t.userId, t.readAt.nullsFirst(), t.createdAt.desc()),
    index('notifications_share_idx').on(t.shareId),
    check(
      'notifications_type_check',
      sql`${t.type} in ('share_received','reaction_received','reply_received','friend_request_received','friend_request_accepted','share_watched')`,
    ),
  ],
);

export const notificationPrefs = pgTable(
  'notification_prefs',
  {
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    type: text('type').notNull(),
    channel: text('channel').notNull(),
    enabled: boolean('enabled').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.userId, t.type, t.channel] }),
    check('notification_prefs_channel_check', sql`${t.channel} in ('push')`),
  ],
);

export const pushTargets = pgTable(
  'push_targets',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    kind: text('kind', { enum: ['webpush', 'expo'] }).notNull(),
    endpoint: text('endpoint').notNull(),
    p256dh: text('p256dh'),
    auth: text('auth'),
    privatePreviews: boolean('private_previews').notNull().default(false),
    createdAt: createdAt(),
    lastSuccessAt: tstz('last_success_at'),
  },
  (t) => [
    uniqueIndex('push_targets_endpoint_key').on(t.endpoint),
    index('push_targets_user_idx').on(t.userId),
    check('push_targets_kind_check', sql`${t.kind} in ('webpush','expo')`),
  ],
);

/** Instance secrets encrypted with a key derived from APP_SECRET (AES-256-GCM), e.g. VAPID. */
export const instanceSecrets = pgTable('instance_secrets', {
  key: text('key').primaryKey(),
  ciphertext: bytea('ciphertext').notNull(),
  createdAt: createdAt(),
});

/** Self-service data exports (FR-ACCT-05, WF-ACCT-4). */
export const exports = pgTable(
  'exports',
  {
    id: uuid('id').primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    includeMedia: boolean('include_media').notNull(),
    state: text('state', { enum: ['queued', 'building', 'ready', 'failed', 'expired'] })
      .notNull()
      .default('queued'),
    objectKey: text('object_key'),
    bytes: bigint('bytes', { mode: 'number' }),
    error: text('error'),
    createdAt: createdAt(),
    readyAt: tstz('ready_at'),
    expiresAt: tstz('expires_at'),
  },
  (t) => [
    index('exports_user_created_idx').on(t.userId, t.createdAt.desc()),
    uniqueIndex('exports_one_active_per_user')
      .on(t.userId)
      .where(sql`${t.state} in ('queued','building')`),
    check(
      'exports_state_check',
      sql`${t.state} in ('queued','building','ready','failed','expired')`,
    ),
  ],
);
